UPDATE promotions SET used_count = 7 WHERE code = 'GIAM10';
UPDATE promotions SET used_count = 8 WHERE code = 'GIAM20';
UPDATE promotions SET used_count = 6 WHERE code = 'GIAM5K';
UPDATE promotions SET used_count = 7 WHERE code = 'GIAM20K';
UPDATE promotions SET used_count = 6 WHERE code = 'KHAITRUONG';
